contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint256 amount, bytes calldata data, bool trySend) public payable {
        require(amount <= address(this).balance, "insufficient balance");
        require(target != address(0), "target zero");

        uint256 cBalanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = c.owner().balance;

        bool withdrawReverted;
        try c.withdraw(amount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        bool sendMoneyReverted;
        if (trySend) {
            try c.sendMoney(target, amount, data) {
                sendMoneyReverted = false;
            } catch {
                sendMoneyReverted = true;
            }
        }

        bool isOwner = (address(this) == c.owner());

        assert(
            isOwner ||
            (withdrawReverted && withdrawAllReverted && (!trySend || sendMoneyReverted) && address(c).balance == cBalanceBefore && c.owner().balance == ownerBalanceBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, bytes calldata data) public payable {
        require(address(this).balance >= amount);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.sendMoney{value: amount}(address(this), amount, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
