contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint depositAmount, uint sendAmount) public payable {
        require(depositAmount > 0);
        require(sendAmount > 0);
        require(address(this).balance >= depositAmount + sendAmount);

        address target = address(0xdead);

        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        (bool s1, ) = address(c).call{value: depositAmount}("");
        require(s1, "deposit failed");

        uint balAfterDeposit = address(c).balance;
        uint depositsAfterDeposit = c.depositsCount();

        uint targetBefore = target.balance;
        bool reverted;
        try c.sendMoney(target, sendAmount, "") {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balAfterSend = address(c).balance;
        uint depositsAfterSend = c.depositsCount();

        assert(
            balAfterDeposit == balBefore + depositAmount &&
            depositsAfterDeposit == depositsBefore + 1 &&
            (
                (reverted && balAfterSend == balAfterDeposit && target.balance == targetBefore && depositsAfterSend == depositsAfterDeposit) ||
                (!reverted && balAfterSend == balAfterDeposit - sendAmount && target.balance == targetBefore + sendAmount && depositsAfterSend == depositsAfterDeposit)
            )
        );
    }

    receive() external payable {}
}

