    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted ? (c.depositsCount() == beforeCount && address(c).balance == beforeBalance) : (c.depositsCount() == beforeCount + 1 && address(c).balance == beforeBalance + amount));
    }
}

