contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        require(address(this).balance >= 1 ether, "insufficient test balance");

        // Fund c so there is something to withdraw.
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "funding failed");

        uint cBefore = address(c).balance;
        uint ownerBefore = c.owner().balance;
        uint depositsBefore = c.depositsCount();

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(address(c).balance == 0 && c.owner().balance == ownerBefore + cBefore);
        } else {
            assert(address(c).balance == cBefore && c.owner().balance == ownerBefore);
        }
    }

    receive() external payable {}
}

